// A flash sale: a virtual waiting room admitting requests in fair, ordered
// batches, and a single authoritative in-memory stock counter that every
// admitted request races against, never selling more than the available stock.
class FlashSale {
    private final Queue<String> waitingRoom = new LinkedList<>(); // strictly ordered, first-come-first-served
    private int remainingStock;
    private int successfulPurchases = 0;

    FlashSale(int initialStock) {
        this.remainingStock = initialStock;
    }

    void joinWaitingRoom(String customerId) {
        waitingRoom.add(customerId);
    }

    // Admits up to batchSize customers from the front of the waiting room.
    List<String> admitNextBatch(int batchSize) {
        List<String> admitted = new ArrayList<>();
        for (int i = 0; i < batchSize && !waitingRoom.isEmpty(); i++) {
            admitted.add(waitingRoom.poll());
        }
        return admitted;
    }

    // The single authoritative decision: succeeds only if stock genuinely remains.
    boolean attemptPurchase(String customerId) {
        if (remainingStock <= 0) {
            return false; // sold out, even though this customer was genuinely admitted
        }
        remainingStock--; // atomic decrement, the one operation that actually enforces the limit
        successfulPurchases++;
        return true;
    }

    int remainingStock() {
        return remainingStock;
    }

    int successfulPurchaseCount() {
        return successfulPurchases;
    }
}

