from collections import deque


class FlashSale:
    # A flash sale: a virtual waiting room admitting requests in fair, ordered
    # batches, and a single authoritative in-memory stock counter that every
    # admitted request races against, never selling more than the available stock.
    def __init__(self, initial_stock):
        self.waiting_room = deque()  # strictly ordered, first-come-first-served
        self.remaining_stock = initial_stock
        self.successful_purchases = 0

    def join_waiting_room(self, customer_id):
        self.waiting_room.append(customer_id)

    def admit_next_batch(self, batch_size):
        admitted = []
        for _ in range(batch_size):
            if not self.waiting_room:
                break
            admitted.append(self.waiting_room.popleft())
        return admitted

    def attempt_purchase(self, customer_id):
        if self.remaining_stock <= 0:
            return False  # sold out, even though this customer was genuinely admitted
        self.remaining_stock -= 1  # atomic decrement, the one operation that actually enforces the limit
        self.successful_purchases += 1
        return True

    def remaining_stock_count(self):
        return self.remaining_stock

    def successful_purchase_count(self):
        return self.successful_purchases


def main():
    sale = FlashSale(3)  # only 3 units available

    # 10 customers join the waiting room in arrival order.
    for i in range(1, 11):
        sale.join_waiting_room(f"customer-{i}")

    # Admission proceeds in fixed-size batches of 5 per tick.
    tick1 = sale.admit_next_batch(5)
    print("Tick 1 admitted:", tick1)
    for customer_id in tick1:
        print(f"  {customer_id}:", "SUCCESS" if sale.attempt_purchase(customer_id) else "SOLD_OUT")

    tick2 = sale.admit_next_batch(5)
    print("Tick 2 admitted:", tick2)
    for customer_id in tick2:
        print(f"  {customer_id}:", "SUCCESS" if sale.attempt_purchase(customer_id) else "SOLD_OUT")

    print("Total successful purchases (should be exactly 3, matching available stock):", sale.successful_purchase_count())
    print("Remaining stock (should be exactly 0):", sale.remaining_stock_count())


if __name__ == "__main__":
    main()

