        waitingRoom.push_back(customerId); // strictly ordered, first-come-first-served
    }

    vector<string> admitNextBatch(int batchSize) {
        vector<string> admitted;
        for (int i = 0; i < batchSize && !waitingRoom.empty(); i++) {
            admitted.push_back(waitingRoom.front());
            waitingRoom.pop_front();
        }
        return admitted;
    }

    bool attemptPurchase(const string& customerId) {
        if (remainingStock <= 0) {
            return false; // sold out, even though this customer was genuinely admitted
        }
        remainingStock--; // atomic decrement, the one operation that actually enforces the limit
        successfulPurchases++;
        return true;
    }

    int remainingStockCount() {
        return remainingStock;
    }

    int successfulPurchaseCount() {
        return successfulPurchases;
    }

private:
    deque<string> waitingRoom;
    int remainingStock;
    int successfulPurchases;
};

